BEGIN;
SET LOCAL ROLE service_role;
DO $$ DECLARE link_id uuid; token_id uuid; result jsonb; hash jsonb:='{"algorithm":"fixture","hash":"private"}'; BEGIN
 INSERT INTO public.redirects(type,slug,target,end_at) VALUES('SHORT','policy-api-fixture','https://example.com','2030-01-01') RETURNING id INTO link_id;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,redirect_ids,created_by,expires_at) VALUES('policy',repeat('f',64),'fixture',ARRAY['links:read','links:write'],ARRAY[link_id],gen_random_uuid(),now()+interval '1 day') RETURNING id INTO token_id;
 result:=public.redirect_policy_resource(link_id,'patch','{"track_conversions":true,"device_targets":{"ios":"/ios"}}',hash,true,token_id);
 IF NOT(result->>'hasPassword')::boolean OR result::text LIKE '%private%' OR result::text LIKE '%password_hash%' THEN RAISE EXCEPTION 'Password state or disclosure failure'; END IF;
 IF NOT(result->'policy'?'expires_at') THEN RAISE EXCEPTION 'Policy patch erased pre-existing expiry'; END IF;
 result:=public.redirect_policy_resource(link_id,'patch','{"geo_targets":{"CH":"/switzerland"}}',p_token_id=>token_id);
 IF NOT(result->>'hasPassword')::boolean OR NOT(result->'policy'->>'track_conversions')::boolean OR result->'policy'->'device_targets'->>'ios'<>'/ios' THEN RAISE EXCEPTION 'Policy merge lost existing fields'; END IF;
 result:=public.redirect_policy_resource(link_id,'patch','{"device_targets":null,"expires_at":null}',p_token_id=>token_id);
 IF result->'policy'?'device_targets' OR result->'policy'?'expires_at' OR NOT(result->'policy'?'geo_targets') THEN RAISE EXCEPTION 'Policy clear failed'; END IF;
 IF NOT EXISTS(SELECT FROM public.redirect_link_policies WHERE redirect_id=link_id AND password_hash=hash) THEN RAISE EXCEPTION 'Unrelated patch erased password'; END IF;
 BEGIN PERFORM public.redirect_policy_resource(link_id,'patch','{"expires_at":"invalid","track_conversions":false}',NULL,true,token_id);RAISE EXCEPTION 'Invalid expiry accepted';EXCEPTION WHEN invalid_datetime_format THEN NULL;END;
 IF NOT EXISTS(SELECT FROM public.redirect_link_policies WHERE redirect_id=link_id AND password_hash=hash AND (policy->>'track_conversions')::boolean) THEN RAISE EXCEPTION 'Failed policy mutation did not roll back'; END IF;
 result:=public.redirect_policy_resource(link_id,'patch','{}',NULL,true,token_id);
 IF (result->>'hasPassword')::boolean THEN RAISE EXCEPTION 'Password clear failed'; END IF;
 PERFORM public.redirect_policy_resource(link_id,'patch','{"device_targets":{"ios":"http://example.com"}}',p_token_id=>token_id);
 BEGIN PERFORM public.redirect_policy_resource(link_id,'patch','{"cloaked":true}',p_token_id=>token_id);RAISE EXCEPTION 'Merged HTTPS guard bypassed';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 FOR i IN 1..20 LOOP IF public.reserve_redirect_policy_password(link_id,token_id)<>0 THEN RAISE EXCEPTION 'Premature password throttle'; END IF; END LOOP;
 IF public.reserve_redirect_policy_password(link_id,token_id)<=0 THEN RAISE EXCEPTION 'Password throttle bypassed'; END IF;
 UPDATE public.redirect_policy_password_limits SET window_started_at=now()-interval '2 hours';
 IF public.reserve_redirect_policy_password(link_id,token_id)<>0 THEN RAISE EXCEPTION 'Password throttle did not reset'; END IF;
 UPDATE public.redirect_policy_password_limits SET attempts=20,window_started_at=now() WHERE bucket='link:'||link_id::text;
 IF public.reserve_redirect_policy_password(link_id,token_id)<=0 THEN RAISE EXCEPTION 'Link hash budget bypassed';END IF;
 UPDATE public.redirect_policy_password_limits SET window_started_at=now()-interval '2 hours';
 PERFORM public.reserve_redirect_policy_password(link_id,token_id);
 UPDATE public.redirect_policy_password_limits SET attempts=100,window_started_at=now() WHERE bucket='global';
 IF public.reserve_redirect_policy_password(link_id,token_id)<=0 THEN RAISE EXCEPTION 'Global hash budget bypassed';END IF;
 UPDATE public.redirect_api_tokens SET scopes=ARRAY['links:read'] WHERE id=token_id;
 BEGIN PERFORM public.redirect_policy_resource(link_id,'patch','{"track_conversions":false}',p_token_id=>token_id);RAISE EXCEPTION 'Read key wrote policy';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE public.redirect_api_tokens SET redirect_ids=ARRAY[gen_random_uuid()] WHERE id=token_id;
 BEGIN PERFORM public.redirect_policy_resource(link_id,'get',p_token_id=>token_id);RAISE EXCEPTION 'Scope escaped';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE public.redirect_api_tokens SET scopes=ARRAY['links:read','links:write'],redirect_ids=ARRAY[link_id],revoked_at=now() WHERE id=token_id;
 BEGIN PERFORM public.reserve_redirect_policy_password(link_id,token_id);RAISE EXCEPTION 'Revoked key reserved hash';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_policy_resource(link_id,'patch','{"track_conversions":false}',p_token_id=>token_id);RAISE EXCEPTION 'Revoked key wrote policy';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $$ BEGIN
 IF has_function_privilege(current_user,'public.redirect_policy_resource(uuid,text,jsonb,jsonb,boolean,uuid)','execute') OR has_function_privilege(current_user,'public.reserve_redirect_policy_password(uuid,uuid,uuid)','execute') THEN RAISE EXCEPTION 'Policy RPC exposed directly';END IF;
END $$;
ROLLBACK;
